    updateEngine(engine: GlobalQnaEngine): void { this.engine = engine; if (this.showingSavedDashboard) { const scrollTop = this.messages.scrollTop; const expanded = this.savedReports.find((report) => report.id === this.expandedReportId); if (expanded) this.showExpandedSavedReport(expanded); else this.showSavedDashboardV2(); requestAnimationFrame(() => { if (this.showingSavedDashboard) this.messages.scrollTop = scrollTop; }); } else if (!this.hasConversation) this.clear(); }

    getState(): { questions: string[]; draft: string; savedReports: SavedReport[]; layoutSettings: QnaLayoutSettings; conversationScrollTop: number; activeView: "conversation" | "saved-dashboard" | "saved-report"; activeSavedReportId: string } { return { questions: this.questions.slice(-20), draft: this.input.value, savedReports: this.savedReports.slice(0, 20), layoutSettings: this.engine.getLayoutSettings(), conversationScrollTop: this.messages.scrollTop, activeView: this.showingSavedDashboard ? (this.expandedReportId ? "saved-report" : "saved-dashboard") : "conversation", activeSavedReportId: this.expandedReportId }; }

    restoreState(state: { questions?: string[]; draft?: string; savedReports?: SavedReport[]; layoutSettings?: Partial<QnaLayoutSettings>; conversationScrollTop?: number; activeView?: "conversation" | "saved-dashboard" | "saved-report"; activeSavedReportId?: string }): void {
        if (state.layoutSettings) this.engine.setLayoutSettings(state.layoutSettings); const storedQuestions = (state.questions || []).slice(-20); const questions = this.engine.getLayoutSettings().conversationMode === "latest" ? storedQuestions.slice(-1) : storedQuestions; this.questions = []; this.savedReports = Array.isArray(state.savedReports) ? state.savedReports.slice(0, 20) : []; this.updateSavedCount(); this.clear();
        questions.forEach((question) => this.submit(question, false)); this.questions = questions;
        this.input.value = String(state.draft || ""); this.renderInputHighlight(); if (state.activeView === "saved-report") { const report = this.savedReports.find((item) => item.id === state.activeSavedReportId); if (report) this.showExpandedSavedReport(report); else this.showSavedDashboardV2(); } else if (state.activeView === "saved-dashboard") this.showSavedDashboardV2(); else { const scrollTop = Number(state.conversationScrollTop); requestAnimationFrame(() => { this.messages.scrollTop = Number.isFinite(scrollTop) ? Math.max(0, scrollTop) : this.messages.scrollHeight; }); }
    }

    private clear(): void {
        this.showingSavedDashboard = false; this.root.classList.remove("is-saved-dashboard"); this.hasConversation = false; this.messages.replaceChildren();
        const hero = document.createElement("section"); hero.className = "askbics-qna__hero";
        const icon = document.createElement("div"); icon.className = "askbics-qna__hero-icon"; icon.textContent = "✦";
        const title = document.createElement("h2"); title.textContent = "What would you like to know?";
        const copy = document.createElement("p"); copy.textContent = "Ask questions in plain language and turn your Power BI data into answers, comparisons and visuals.";
        const prompts = document.createElement("div"); prompts.className = "askbics-qna__prompt-grid";
        this.engine.starterPrompts().forEach((item) => { const button = document.createElement("button"); button.type = "button"; button.dataset.tooltip = item.prompt; button.setAttribute("aria-label", `${item.title}: ${item.prompt}`); const badge = document.createElement("span"); badge.textContent = item.icon; const text = document.createElement("span"); const strong = document.createElement("strong"); strong.textContent = item.title; const small = document.createElement("small"); small.textContent = item.prompt; text.append(strong, small); button.append(badge, text); button.addEventListener("click", () => this.submit(item.prompt)); prompts.appendChild(button); });
        hero.append(icon, title, copy, prompts); this.messages.appendChild(hero);
    }

    private submit(question?: string, persist = true): void {
        const text = String(question ?? this.input.value).trim(); if (!text) return;
        if (this.engine.getLayoutSettings().conversationMode === "latest" && this.hasConversation) { this.messages.replaceChildren(); this.questions = []; }
        if (!this.hasConversation) { this.messages.replaceChildren(); this.hasConversation = true; }
        this.input.value = ""; this.renderInputHighlight(); this.closeSuggestions(); this.addBubble(this.displayQuestion(text), "user", this.messages, text);
        try { this.render(this.engine.answer(text), text); } catch (error) { this.addBubble(`I could not answer that question: ${String((error as Error)?.message || error)}`, "assistant"); }
        if (persist) { this.questions.push(text); this.onStateChanged?.(); }
    }

    private render(response: QnaResponse, question: string): void {
        const answer = document.createElement("section"); answer.className = "askbics-qna__answer";
        const answerHead = document.createElement("div"); answerHead.className = "askbics-qna__answer-head";
        const answerLabel = document.createElement("span"); answerLabel.textContent = response.chart ? "Chart answer" : response.table ? "Table answer" : response.kpi ? "KPI answer" : "Answer";
        const save = document.createElement("button"); save.type = "button"; save.className = "askbics-qna__save"; const saveIcon = document.createElement("span"); saveIcon.textContent = "＋"; save.append(saveIcon, document.createTextNode(" Save to reports")); save.setAttribute("aria-label", "Save this answer to Saved Reports"); save.addEventListener("click", () => this.saveReport(question, response, save));
        if (this.savedReports.some((item) => item.question.toLowerCase() === question.toLowerCase())) { save.classList.add("is-saved"); save.replaceChildren(); const savedIcon = document.createElement("span"); savedIcon.textContent = "✓"; save.append(savedIcon, document.createTextNode(" Saved")); save.disabled = true; }
        answerHead.append(answerLabel, save); answer.appendChild(answerHead); this.messages.appendChild(answer);
        if (response.text) this.addBubble(response.text, "assistant", answer);
        if (response.kpi) {
            const card = document.createElement("div"); card.className = "askbics-qna__kpi";
            const title = document.createElement("div"); title.className = "askbics-qna__kpi-title"; title.textContent = response.kpi.title;
            const value = document.createElement("div"); value.className = "askbics-qna__kpi-value"; value.textContent = response.kpi.value;
            const subtitle = document.createElement("div"); subtitle.className = "askbics-qna__kpi-subtitle"; subtitle.textContent = response.kpi.subtitle || "";
            card.append(title, value, subtitle); answer.appendChild(card);
        }
        if (response.table) answer.appendChild(this.table(response.table, question, (nextQuestion) => this.submit(nextQuestion)));
        if (response.chart) answer.appendChild(this.chart(response.chart));
        if (response.suggestions?.length) this.addPromptChips(response.suggestions, answer);
        this.messages.scrollTop = this.messages.scrollHeight;
    }

