        const closeFilterMenu = () => { filterMenu?.remove(); filterMenu = null; }; const updateClearFilters = () => { const count = filters.filter(Boolean).length; clearFilters.hidden = count === 0; clearFilterCount.textContent = String(count); clearFilters.setAttribute("aria-label", count ? `Clear ${count} active table ${count === 1 ? "filter" : "filters"}` : "No active table filters"); };
