    private displayQuestion(question: string): string { const match = question.match(/^\s*(table|matrix)\s*;\s*rows\s*:\s*([^;]*)\s*;\s*columns\s*:\s*([^;]*)\s*;\s*values\s*:\s*(.*)\s*$/i); if (!match) return question; const mode = match[1].toLowerCase(); const rows = match[2].split(/\s*>\s*|\s*,\s*/).map((item) => item.trim()).filter(Boolean); const columns = match[3].split(/\s*>\s*|\s*,\s*/).map((item) => item.trim()).filter(Boolean); const measures = match[4].split(/\s*,\s*/).map((item) => item.trim()).filter(Boolean); const measureText = measures.join(" and ") || "values"; const rowText = rows.length ? ` by ${rows.join(" and ")}` : ""; const columnText = mode === "matrix" && columns.length ? `, with columns by ${columns.join(" and ")}` : ""; return `Show ${measureText}${rowText}${columnText} as a ${mode}.`; }

    private addBubble(text: string, role: "user" | "assistant", parent: HTMLElement = this.messages, editValue = text): void { const bubble = document.createElement("div"); bubble.className = `askbics-qna__bubble askbics-qna__bubble--${role}`; const content = document.createElement("span"); content.className = "askbics-qna__bubble-text"; content.textContent = text; content.addEventListener("mousedown", (event) => event.stopPropagation()); bubble.appendChild(content); if (role === "user") { const edit = document.createElement("button"); edit.type = "button"; edit.className = "askbics-qna__edit"; edit.textContent = "✎"; edit.setAttribute("aria-label", "Edit this question"); edit.dataset.tooltip = "Edit question"; edit.addEventListener("click", () => { this.input.value = editValue; this.renderInputHighlight(); this.showAutocomplete(); this.input.focus(); this.input.setSelectionRange(editValue.length, editValue.length); }); bubble.appendChild(edit); } parent.appendChild(bubble); }
