    private saveReport(question: string, response: QnaResponse, button: HTMLButtonElement): void { const existing = this.savedReports.find((item) => item.question.toLowerCase() === question.toLowerCase()); if (!existing) { const name = response.chart?.title || response.kpi?.title || response.table?.columns.join(" by ") || question; const random = new Uint32Array(2); crypto.getRandomValues(random); this.savedReports.push({ id: `${Date.now()}-${random[0].toString(36)}${random[1].toString(36)}`, name, question, createdAt: Date.now(), size: response.kpi ? "small" : response.chart ? "large" : "medium" }); this.savedReports = this.savedReports.slice(-20); } button.classList.add("is-saved"); button.replaceChildren(); const icon = document.createElement("span"); icon.textContent = "✓"; button.append(icon, document.createTextNode(" Saved")); button.disabled = true; this.updateSavedCount(); this.onStateChanged?.(); }
